                        <div style="height:100%;font-size: 28px">
                            <img style="height:55px;" src="../../assets/img/logo_1.png"/> 大学生竞赛管理系统
                        </div>
                    </el-menu-item>
                    <!--          <el-submenu index="2">-->
                    <!--            <template slot="title">我的管理</template>-->
                    <!--            <el-menu-item index="/teacher/comp">竞赛管理</el-menu-item>-->
                    <!--            <el-menu-item index="/teacher/project">项目管理</el-menu-item>-->
                    <!--            <el-menu-item index="/teacher/gonggao">公告管理</el-menu-item>-->
                    <!--          </el-submenu>-->
                    <!--          <el-menu-item index="/teacher/home">个人中心</el-menu-item>-->

                    <el-menu-item type="success" size="small" round icon="el-icon-user-solid" style="float: right;">
                        <span type="danger" size="small" round @click="退出登录()" style="margin-right: 30px"><i class="el-icon-switch-button"></i>退出登录</span>
                    </el-menu-item>
                    <el-menu-item type="success" size="small" round icon="el-icon-user-solid" style="float: right">
                      <i class="el-icon-user-solid"></i>  {{this.$store.state.nickname}} 老师
                    </el-menu-item>
                </el-menu>
            </el-header>
            <el-container>
                <el-aside width="220px" style="height: 100%; background: linear-gradient(to bottom right,#4682B4,rgba(105, 206, 235, 0.8))">
                    <el-menu
                            :default-active="this.$router.path"
                            router
                            text-color="1D6FA3"
                            active-text-color="black"
                            style="border-right: 2px;
                   background: linear-gradient(to bottom right,rgba(101,253,240,0),rgba(29,111,163,0));    "
                            class="el-menu-vertical-demo"
                    >
                        <el-menu-item index="/teacher/index">
                            <i class="el-icon-menu"></i>
                            <span slot="title">首页</span>
                        </el-menu-item>

                        <el-menu-item index="/teacher/comp">
                            <i class="el-icon-wallet"></i>
                            <span slot="title">竞赛信息列表</span>
                        </el-menu-item>

                        <el-menu-item index="/teacher/apply">
                            <i class="el-icon-bank-card"></i>
                            <span slot="title">竞赛申请管理</span>
                        </el-menu-item>

                        <el-menu-item index="/teacher/project">
                            <i class="el-icon-files"></i>
                            <span slot="title">竞赛队伍管理</span>
                        </el-menu-item>

                        <el-menu-item index="/teacher/xinxi">
                            <i class="el-icon-postcard"></i>
                            <span slot="title">我的信息管理</span>
                        </el-menu-item>

                        <el-menu-item index="/teacher/home">
                            <i class="el-icon-user-solid"></i>
                            <span slot="title">个人管理中心</span>
                        </el-menu-item>
                    </el-menu>
                </el-aside>
                <el-main style="background-color: rgba(165,165,165,0.43)">
                    <router-view/>
                </el-main>
            </el-container>
        </el-container>
    </div>
</template>

<script>
    import api from '../../main.js'

    export default {
        name: "teacher",
        data() {
            return {
                receiver: this.$store.state.receiver,
                xinxiList: []
            };
        },
        mounted() {
            this.getMessage();
        },

        methods: {
            getMessage() {
                let that = this;
                that.$axios
                    .get(api + `/msg/getUnReadListPopup/` + that.receiver)
                    .then(function (response) {
                        that.xinxiList = response.data;
                        that.showMessage();
                    })
                    .catch(function (error) {
                    });
            },
            showMessage: async function () {
                let that = this;
                /**创建一个节点元素 */
                const h = that.$createElement;
                for (let i = 0; i < that.xinxiList.length; i++) {
                    await that.$notify({
                        title: that.xinxiList[i].title,
                        message: that.xinxiList[i].content,
                        type: that.xinxiList[i].type == 2 ? 'success' : 'warning',
                        duration: 7000,
                        offset: 55
                    });
                }
            },
            退出登录() {
                this.$confirm("此操作将退出登录, 是否继续?", "注意", {
                    confirmButtonText: "确定",
                    cancelButtonText: "取消",
                    type: "warning"
                })
                    .then(() => {
                        //清除store.state.userinfo 和 store.state.islogin
                        this.$store.commit("logout", false);
                        //从window.sessionStorage 中删除相应内容
                        window.sessionStorage.setItem("username", "");

                        window.sessionStorage.setItem("id", "");

                        window.sessionStorage.setItem("nickname", "");

                        window.sessionStorage.setItem("token", "");

                        window.sessionStorage.setItem("islogin", false);

                        this.$message({
                            type: "success",
                            message: "已退出登录!"
                        });
                        //跳转登陆页面
                        this.$router.push({path: "/"});
                    })
                    .catch(() => {
                        // this.$message({
                        //   type: "waring",
                        //   message: "未知错误！"
                        // });
                    });
            }
        }
    };
</script>

